const HizbPart muqaddima = HizbPart(
  id: 'muqaddima',
  title: 'مقدمة',
  content: r'''بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ

الحَمْدُ لِلَّهِ الَّذِي نَوَّرَ قُلُوبَ الصَّالِحِينَ بِذِكْرِهِ ۞ وَأَنْطَقَ أَلْسِنَتَهُمْ بِشُكْرِهِ ۞ وَالصَّلَاةُ وَالسَّلَامُ عَلَى سَيِّدِنَا مُحَمَّدٍ الَّذِي مَا تَرَكَ شَيْئًا يُقَرِّبُ إِلَى اللَّهِ تَعَالَى إِلَّا وَدَعَا إِلَيْهِ ۞ وَلَا أَدَبًا يَصْلُحُ أَنْ يَكُونَ العَبْدُ بِهِ مَعَ رَبِّهِ إِلَّا وَحَثَّ عَلَيْهِ ۞ وَرَضِيَ اللَّهُ عَنْ آلِ بَيْتِهِ الطَّاهِرِينَ ۞ وَأَصْحَابِهِ المُتَّقِينَ ۞ وَعَلَى مَنِ اتَّبَعَهُمْ بِإِحْسَانٍ إِلَى يَوْمِ الدِّينِ

أَمَّا بَعْدُ ۞ فَإِنَّ الدُّعَاءَ مِنْ أَجَلِّ العِبَادَاتِ ۞ وَأَقْرَبِ وَسَائِلِ تَحْصِيلِ الخَيْرَاتِ ۞ إِذْ يَقْضِي اللَّهُ عَزَّ وَجَلَّ بِهِ الحَاجَاتِ ۞ وَيَدْفَعُ البَلِيَّاتِ ۞ وَيَكْشِفُ مَا أَهَمَّ مِنَ المُلِمَّاتِ ۞ وَيَرْفَعُ إِلَى عَلِيِّ الدَّرَجَاتِ

وَقَدْ أَرْشَدَ إِلَى فَضْلِهِ القُرْآنُ المَجِيدُ ۞ الَّذِي §Q§فصلت: ٤٢|لا يَأتيهِ البٰطِلُ مِن بَينِ يَدَيهِ وَلا مِن خَلفِهِ تَنزيلٌ مِن حَكيمٍ حَميدٍ ٤٢§Q§ ۞ فَهُوَ مَلِيءٌ بِالدُّعَاءِ وَالطَّلَبِ لَهُ ۞ وَجَمِيعُ الأَنْبِيَاءِ عَلَيْهِمُ الصَّلَاةُ وَالسَّلَامُ قَدْ لَهِجُوا بِهِ ۞ وَفَزِعُوا عِنْدَ الشَّدَائِدِ إِلَيْهِ ۞ لَا سِيَّمَا إِمَامُهُمْ وَخَاتِمُهُمْ سَيِّدُنَا وَنَبِيُّنَا مُحَمَّدٌ ﷺ

وَقَدْ عَلَّمَ نَبِيُّنَا ﷺ الدُّعَاءَ لِأُمَّتِهِ ۞ وَاجْتَمَعَ فِي دُعَائِهِ العِلْمُ بِالتَّوْحِيدِ ۞ وَالنَّصِيحَةُ لِلْأُمَّةِ ۞ وَالعِلْمُ بِاللُّغَةِ ۞ فَكَانَتْ أَدْعِيَتُهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ مُقَدَّمَةً عَلَى غَيْرِهَا بِالإِطْلَاقِ ۞ كَمَا أَنَّ لَفْظَهَا وَسِيلَةٌ لِقَبُولِهَا ۞ وَبَابٌ لِكُلِّ العُلُومِ الشَّرِيفَةِ

ثُمَّ اسْتَنَّ بِسُنَّتِهِ وَاهْتَدَى بِهَدْيِهِ أَصْحَابُهُ رَضِيَ اللَّهُ عَنْهُمْ ۞ وَصَدَرَتْ عَنْهُمْ أَدْعِيَةٌ مُبَارَكَةٌ لَمْ يَسْمَعُوهَا مِنْهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ ۞ فَأَقَرَّهُمْ عَلَيْهَا عِنْدَ سَمَاعِهَا ۞ مِنْ ذَلِكَ أَنَّهُ ﷺ سَمِعَ رَجُلًا يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ ۞ الأَحَدُ الصَّمَدُ ۞ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ ۞ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ۞ فَقَالَ لَهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ: لَقَدْ سَأَلْتَ اللَّهَ بِاسْمِهِ الأَعْظَمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ ۞ وَإِذَا سُئِلَ بِهِ أَعْطَى

وَفِي حَدِيثِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ ﷺ سَمِعَ رَجُلًا يَقُولُ: يَا ذَا الجَلَالِ وَالإِكْرَامِ ۞ فَقَالَ لَهُ ﷺ: قَدِ اسْتُجِيبَ لَكَ ۞ فَسَلْ

وَفِي حَدِيثِ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ مَرَّ بِأَبِي عَيَّاشٍ زَيْدِ بْنِ الصَّامِتِ الزُّرَقِيِّ ۞ وَهُوَ يُصَلِّي وَيَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الحَمْدَ ۞ لَا إِلَهَ إِلَّا أَنْتَ ۞ يَا حَنَّانُ يَا مَنَّانُ ۞ يَا بَدِيعَ السَّمَوَاتِ وَالأَرْضِ ۞ يَا ذَا الجَلَالِ وَالإِكْرَامِ ۞ فَقَالَ ﷺ: لَقَدْ دَعَا اللَّهَ بِاسْمِهِ الأَعْظَمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ ۞ وَإِذَا سُئِلَ بِهِ أَعْطَى

وَقَدْ أَدْخَلَ الإِمَامُ مَالِكٌ رَحِمَهُ اللَّهُ فِي بَابِ دُعَاءِ النَّبِيِّ ﷺ مِنَ المُوَطَّأِ قَوْلَ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ عِنْدَ قِيَامِهِ مِنَ اللَّيْلِ مُنَاجِيًا رَبَّهُ تَبَارَكَ وَتَعَالَى: نَامَتِ العُيُونُ ۞ وَهَدَأَتِ الجُفُونُ ۞ وَلَمْ يَبْقَ إِلَّا يَا حَيُّ يَا قَيُّومُ إِشَارَةً إِلَى مَشْرُوعِيَّةِ الأَدْعِيَةِ الَّتِي يُلْهَمُهَا الإِنْسَانُ وَتُتْلَى عَلَى لِسَانِهِ مِنَ الكَلِمِ الطَّيِّبِ وَالذِّكْرِ السَّالِمِ مِنَ الاعْتِرَاضِ ۞ وَأَنَّهَا مُلْحَقَةٌ بِأَدْعِيَةِ السُّنَّةِ وَالأَذْكَارِ المَشْرُوعَةِ

وَمِنْ هُنَا صَدَرَتِ الكَثِيرُ مِنَ الأَدْعِيَةِ عَنِ العُلَمَاءِ الرَّبَّانِيِّينَ وَالأَوْلِيَاءِ وَالصَّالِحِينَ ۞ المُهْتَدِينَ بِهَدْيِ النَّبِيِّ ﷺ ۞ المُسْتَنِّينَ بِسُنَّتِهِ وَبِسُنَّةِ أَصْحَابِهِ رَضِيَ اللَّهُ عَنْهُمْ ۞ فَكَانَتْ مَكْسُوَّةً بِكِسْوَةِ العُبُودِيَّةِ ۞ وَارِدَةً مِنْ بِسَاطِ الفَقْرِ وَالذِّلَّةِ وَالخُشُوعِ ۞ وَبِلِسَانِ الإِنَابَةِ وَالخَشْيَةِ وَالخُضُوعِ ۞ فَصَارَتْ بَرَكَتُهَا عَظِيمَةً ۞ لِصُدُورِهَا عَنْ قُلُوبِهِمُ الكَرِيمَةِ ۞ وَمِنْ شَوَاهِدِ ذَلِكَ حُسْنُ تَأْثِيرِهَا فِي سَامِعِيهَا ۞ بِبَرَكَةِ صِدْقِ قَائِلِيهَا وَصِحَّةِ مَعَانِيهَا

وَمِنْ أَبْرَزِ تِلْكَ الأَدْعِيَةِ أَدْعِيَةُ الشَّيْخِ الإِمَامِ أَبِي الحَسَنِ الشَّاذِلِيِّ رَحِمَهُ اللَّهُ ( ت٦٥٦هـ ) ۞ وَتُسَمَّى أَيْضًا بِالأَحْزَابِ ۞ لِأَنَّ الحِزْبَ هُوَ مَجْمُوعُ أَذْكَارٍ وَأَدْعِيَةٍ وَتَوَجُّهَاتٍ وُضِعَتْ لِلذِّكْرِ وَالتَّذْكِيرِ ۞ وَالتَّعَوُّذِ مِنَ الشَّرِّ ۞ وَطَلَبِ الخَيْرِ ۞ وَاسْتِنَاحِ المَعَارِفِ ۞ وَحُصُولِ العِلْمِ ۞ مَعَ جَمْعِ القَلْبِ عَلَى اللَّهِ سُبْحَانَهُ بِذَلِكَ

وَقَدْ أَجَادَ الشَّيْخُ الرَّبَّانِيُّ أَبُو العَبَّاسِ أَحْمَدُ زَرُّوقٌ الفَاسِيُّ ( ت٨٩٩هـ ) فِي وَصْفِ أَدْعِيَةِ الشَّيْخِ الإِمَامِ أَبِي الحَسَنِ الشَّاذِلِيِّ بِقَوْلِهِ: وَاعْلَمْ أَنَّ أَحْزَابَ الشَّيْخِ رَضِيَ اللَّهُ عَنْهُ جَامِعَةٌ بَيْنَ إِفَادَةِ العِلْمِ ۞ وَآدَابِ التَّوَجُّهِ ۞ وَتَعْرِيفِ الطَّرِيقَةِ ۞ وَتَلْوِيحِ الحَقِيقَةِ ۞ وَذِكْرِ جَلَالِ اللَّهِ وَعَظَمَتِهِ وَكِبْرِيَائِهِ ۞ وَذِكْرِ حَقَارَةِ النَّفْسِ وَخِسَّتِهَا ۞ وَالتَّنْبِيهِ عَلَى خُدَعِهَا وَغَوَائِلِهَا ۞ وَالإِشَارَةِ لِوَصْفِ الدُّنْيَا وَالخَلْقِ ۞ وَطَرِيقِ الفِرَارِ مِنْ ذَلِكَ وَوَجْهِ حُصُولِهِ ۞ وَالتَّذْكِيرِ بِالذُّنُوبِ وَالعُيُوبِ وَوَجْهِ التَّنَصُّلِ مِنْهَا ۞ مَعَ الدَّلَالَةِ عَلَى خَاصِّ التَّوْحِيدِ وَخَالِصِهِ ۞ وَاتِّبَاعِ الشَّرْعِ وَمَطَالِبِهِ ۞ فَهِيَ تَعْلِيمٌ فِي قَالَبِ التَّوَجُّهِ ۞ وَتَوَجُّهٌ فِي قَالَبِ التَّعْلِيمِ ۞ مَنْ نَظَرَهَا مِنْ حَيْثُ العِلْمُ وَجَدَهُ كَائِنًا فِيهَا ۞ وَمَنْ نَظَرَهَا مِنْ حَيْثُ العَمَلُ فَهِيَ عَيْنُهُ ۞ وَمَنْ نَظَرَهَا مِنْ حَيْثُ الحَالُ وَجَدَهُ كَامِنًا فِيهَا ۞ وَقَدْ شَهِدَ شَاهِدُهَا بِذَلِكَ عِنْدَ الخَاصِّ وَالعَامِّ ۞ فَلَا يَسْمَعُ أَحَدٌ مِنْ كَلَامِهَا شَيْئًا إِلَّا وَجَدَ لَهُ أَثَرًا فِي نَفْسِهِ ۞ وَلَا يَقْرَؤُهَا إِلَّا كَانَ لَهُ مِثْلُ ذَلِكَ ۞ مَا لَمْ يَكُنْ مَشْغُولًا بِبَلْوَى ۞ أَوْ مَشْغُوفًا بِدُنْيَا ۞ أَوْ مَصْرُوفًا بِدَعْوَى ۞ أَعَاذَنَا اللَّهُ مِنَ البَلَاءِ

وَلِذَلِكَ اعْتَنَى بِشَرْحِهَا الأَفَاضِلُ المُحَصِّلُونَ ۞ وَتَكَلَّمَ عَلَى مَعَانِيهَا الأَئِمَّةُ الرَّاسِخُونَ ۞ وَحَفِظَهَا أَكَابِرُ العُلَمَاءِ ۞ وَاعْتَنَى بِهَا الأَخْيَارُ الصُّلَحَاءُ ۞ كَيْفَ لَا وَقَدِ اشْتَمَلَتْ عَلَى الحَقَائِقِ الإِيمَانِيَّةِ الفَائِقَةِ ۞ فِي ثَوْبِ العِبَارَاتِ البَلِيغَةِ الرَّائِقَةِ ۞ لَا سِيَّمَا وَأَنَّهَا صَدَرَتْ مِنْ إِمَامٍ سُنِّيٍّ شَهِدَ لَهُ أَكَابِرُ عُلَمَاءِ الشَّرِيعَةِ بِالوِلَايَةِ وَالعِرْفَانِ ۞ وَالاسْتِقَامَةِ عَلَى طَرِيقِ الجَادَّةِ الَّتِي أَتَى بِهَا نَبِيُّنَا عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ

فَقَدْ قَالَ الإِمَامُ تَقِيُّ الدِّينِ ابْنُ دَقِيقِ العِيدِ ( ت٧٠٢هـ ) رَحِمَهُ اللَّهُ: مَا رَأَيْتُ أَعْرَفَ بِاللَّهِ مِنَ الشَّيْخِ أَبِي الحَسَنِ الشَّاذِلِيِّ رَضِيَ اللَّهُ عَنْهُ

وَحَلَّاهُ الشَّيْخُ الإِمَامُ الفَقِيهُ المَالِكِيُّ ابْنُ الحَاجِّ العَبْدَرِيُّ ( ت٧٣٧هـ ) رَحِمَهُ اللَّهُ بِقَوْلِهِ: سَيِّدِي الشَّيْخُ الجَلِيلُ أَبُو الحَسَنِ الشَّاذِلِيُّ

وَقَالَ فِي شَأْنِهِ الإِمَامُ تَاجُ الدِّينِ السُّبْكِيُّ ( ٧٧١هـ ) رَحِمَهُ اللَّهُ: «الشَّيْخُ العَارِفُ أَبُو الحَسَنِ الشَّاذِلِيُّ ۞ كَانَ سَيِّدَ عَصْرِهِ وَبَرَكَةَ زَمَانِهِ» ۞ وَحَلَّاهُ أَيْضًا بِقَوْلِهِ: الشَّيْخُ الكَبِيرُ وَلِيُّ اللَّهِ أَبُو الحَسَنِ الشَّاذِلِيُّ

وَقَالَ عَنْهُ الشَّيْخُ مُحَمَّدُ بْنُ عَبْدِ الدَّائِمِ المَعْرُوفُ بِابْنِ بِنْتِ المَيْلَقِ ( ت٧٩٧هـ ) رَحِمَهُ اللَّهُ: هُوَ الشَّيْخُ السَّيِّدُ الشَّرِيفُ العَالِمُ العَلَّامَةُ الوَاحِدُ فِي عَصْرِهِ فِي طَرِيقِ التَّصَوُّفِ وَعِلْمِ السُّلُوكِ ۞ بِاتِّفَاقِ مَنْ يُعَوَّلُ عَلَيْهِ مِنْ أَهْلِ زَمَانِهِ

وَقَالَ الإِمَامُ الفَقِيهُ المَالِكِيُّ أَبُو القَاسِمِ البُرْزُلِيُّ ( ت٨٤١هـ ) رَحِمَهُ اللَّهُ: الشَّيْخُ أَبُو الحَسَنِ الشَّاذِلِيُّ مِنْ أَهْلِ عِلْمِ الحَقَائِقِ ۞ وَمَعْرِفَةِ الدَّقَائِقِ ۞ وَأَسْرَارٍ كَثِيرَةٍ مِنْ عِلْمِ التَّوْحِيدِ ۞ وَمِمَّنْ نَوَّرَ اللَّهُ قَلْبَهُ لِلْغَوْصِ فِي عِلْمِ التَّنْزِيلِ ۞ وَحِكْمَةِ السُّنَّةِ ۞ وَخَصَائِصِ العُلُومِ الرَّبَّانِيَّةِ ۞ وَذَلِكَ مَحْفُوظٌ عَنْهُ ۞ ظَاهِرٌ مِنْ كَلَامِهِ وَأَحْزَابِهِ ۞ وَهُوَ مِنَ العُلَمَاءِ بِاللَّهِ تَعَالَى وَبِأَمْرِهِ ۞ وَمِنْ أَصْحَابِ الأَحْوَالِ ۞ وَمِنْ رِجَالِ الآخِرَةِ ۞ وَعُلَمَاءِ الإِسْلَامِ ظَاهِرًا وَبَاطِنًا

وَقَالَ الإِمَامُ جَلَالُ الدِّينِ السُّيُوطِيُّ ( ت٩١١هـ ) رَحِمَهُ اللَّهُ: أَبُو الحَسَنِ الشَّاذِلِيُّ إِمَامُ أَرْبَابِ القُلُوبِ فِي زَمَانِهِ

فَهَذِهِ الشَّهَادَاتُ وَنَظَائِرُهَا الكَثِيرَةُ دَالَّةٌ عَلَى سَدَادِ مَنْهَجِيَّةِ وَطَرِيقَةِ الشَّيْخِ أَبِي الحَسَنِ الشَّاذِلِيِّ رَحِمَهُ اللَّهُ ۞ وَأَنَّهُ كَانَ مِنَ المُعْتَصِمِينَ بِالكِتَابِ وَالسُّنَّةِ ۞ وَعَلَى ذَلِكَ دَلَّتْ كَلِمَاتٌ صَرِيحَةٌ وَصَلَتْنَا عَنْهُ وَاشْتَهَرَتْ ۞ مِنْهَا: 

قَوْلُهُ رَحِمَهُ اللَّهُ: «كُلُّ عِلْمٍ تَسْبِقُ إِلَيْكَ فِيهِ الخَوَاطِرُ ۞ وَتَمِيلُ إِلَيْهِ النَّفْسُ ۞ وَتَلْتَذُّ بِهِ الطَّبِيعَةُ ۞ فَارْمِ بِهِ وَإِنْ كَانَ حَقًّا ۞ وَخُذْ بِعِلْمِ اللَّهِ الَّذِي أَنْزَلَهُ عَلَى رَسُولِهِ ﷺ ۞ وَاقْتَدِ بِهِ وَبِالخُلَفَاءِ وَالصَّحَابَةِ وَالتَّابِعِينَ مِنْ بَعْدِهِ ۞ وَبِالأَئِمَّةِ الهُدَاةِ المُبَرَّئِينَ عَنِ الهَوَى وَمُتَابَعَتِهِ ۞ تَسْلَمْ مِنَ الشُّكُوكِ وَالظُّنُونِ وَالأَوْهَامِ ۞ وَالدَّعَاوَى الكَاذِبَةِ المُضِلَّةِ عَنِ الهُدَى وَحَقَائِقِهِ»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «لَوْ عَارَضَ كَشْفُكَ الكِتَابَ وَالسُّنَّةَ فَتَمَسَّكْ بِالكِتَابِ وَالسُّنَّةِ ۞ وَدَعِ الكَشْفَ ۞ وَقُلْ لِنَفْسِكَ: إِنَّ اللَّهَ تَعَالَى قَدْ ضَمِنَ لِيَ العِصْمَةَ بِالكِتَابِ وَالسُّنَّةِ ۞ وَلَمْ يَضْمَنْهَا فِي جَانِبِ الكَشْفِ وَلَا الإِلْهَامِ وَلَا المُشَاهَدَةِ ۞ إِلَّا بَعْدَ عَرْضِهِ عَلَى الكِتَابِ وَالسُّنَّةِ»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «مِنْ أَجَلِّ مَوَاهِبِ اللَّهِ الرِّضَا بِمَوَاقِعِ القَضَاءِ ۞ وَالصَّبْرُ عِنْدَ نُزُولِ البَلَاءِ ۞ وَالتَّوَكُّلُ عَلَى اللَّهِ عِنْدَ الشَّدَائِدِ ۞ وَالرُّجُوعُ إِلَيْهِ عِنْدَ النَّوَائِبِ ۞ فَمَنْ خَرَجَتْ لَهُ هَذِهِ الأَرْبَعُ مِنْ خَزَائِنِ الأَعْمَالِ عَلَى بِسَاطِ المُجَاهَدَةِ وَمُتَابَعَةِ السُّنَّةِ وَالاقْتِدَاءِ بِالأَئِمَّةِ فَقَدْ صَحَّتْ وِلَايَتُهُ لِلَّهِ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ ۞ §Q§المائدة: ٥٦|وَمَن يَتَوَلَّ اللَّهَ وَرَسولَهُ وَالَّذينَ ءامَنوا فَإِنَّ حِزبَ اللَّهِ هُمُ الغٰلِبونَ ٥٦§Q§»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «اعْلَمْ أَنَّكَ إِذَا أَرَدْتَ أَنْ يَكُونَ لَكَ نَصِيبٌ مِمَّا لِأَوْلِيَاءِ اللَّهِ تَعَالَى فَعَلَيْكَ بِرَفْضِ النَّاسِ جُمْلَةً ۞ إِلَّا مَنْ يَدُلُّكَ عَلَى اللَّهِ بِإِشَارَةٍ صَادِقَةٍ وَأَعْمَالٍ ثَابِتَةٍ لَا يَنْقُضُهَا كِتَابٌ وَلَا سُنَّةٌ»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «ارْجِعْ عَنْ مُنَازَعَةِ رَبِّكَ تَكُنْ مُوَحِّدًا ۞ وَاعْمَلْ بِأَرْكَانِ الشَّرْعِ تَكُنْ سُنِّيًّا ۞ وَاجْمَعْ بَيْنَهُمَا تَكُنْ مُحَقِّقًا»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «مَوْتُ النَّفْسِ ـ يَعْنِي خِصَالَهَا الذَّمِيمَةَ ـ بِالعِلْمِ ۞ وَالمَعْرِفَةِ ۞ وَالاقْتِدَاءِ بِالكِتَابِ وَالسُّنَّةِ»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «مَنْ دَعَا إِلَى اللَّهِ تَعَالَى بِغَيْرِ مَا دَعَا بِهِ رَسُولُ اللَّهِ ﷺ فَهُوَ بِدْعِيٌّ»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «النَّاظِرُ فِي قَوْلِي مُعْتَقِدٌ وَمُنْتَقِدٌ ۞ وَكُلٌّ مِنْهُمَا عَلَى ضَرْبَيْنِ ۞ فَمُعْتَقِدٌ يَعْتَقِدُ لَفْظَهُ وَمَعْنَاهُ ۞ وَمُعْتَقِدٌ يَعْتَقِدُ لَفْظَهُ وَلَا يَعْقِلُ مَعْنَاهُ ۞ وَمُنْتَقِدٌ يَتَحَرَّزُ لَفْظَهُ وَمَعْنَاهُ ۞ طُوبَى لَهُ ثُمَّ طُوبَى لَهُ ۞ وَمُنْتَقِدٌ يُحَرِّفُ لَفْظَهُ وَمَعْنَاهُ خَسِرَ دُنْيَاهُ وَأُخْرَاهُ»

وَقَوْلُهُ رَحِمَهُ اللَّهُ: «الشَّرْعُ نَقَّادٌ عَلَيَّ وَلِي ۞ بِهِ آخُذُ ۞ وَبِهِ يُؤْخَذُ مَا يُؤْخَذُ عَنِّي ۞ وَهُوَ طَرِيقِي وَطَرِيقُ مَنْ أَرَادَ أَنْ يَصْحَبَنِي ۞ وَإِلَّا فَإِنِّي بَرِيءٌ مِنْهُ»

وَلِأَجْلِ سَدَادِ عَقِيدَةِ وَطَرِيقَةِ الشَّيْخِ الإِمَامِ أَبِي الحَسَنِ الشَّاذِلِيِّ رَحِمَهُ اللَّهُ حَتَّى قَالَ السُّيُوطِيُّ رَحِمَهُ اللَّهُ: «هِيَ فِي المُتَأَخِّرِينَ نَظِيرُ طَرِيقَةِ الجُنَيْدِ فِي المُتَقَدِّمِينَ» ـ وَجَّهَ الفُقَهَاءُ وَعُلَمَاءُ الشَّرِيعَةِ مَا يُشْكِلُ فَهْمُهُ مِنَ الكَلِمَاتِ الوَارِدَةِ فِي أَدْعِيَتِهِ ۞ كَالَّتِي لَمْ يُعْرَفْ مِنْ جِهَةِ الوَضْعِ اللُّغَوِيِّ مَعْنَاهَا ۞ وَاسْتَثْنَوْهَا مِمَّا لَا يَجُوزُ الدُّعَاءُ بِهِ ۞ فَقَالَ الفَقِيهُ المَالِكِيُّ العَلَّامَةُ أَحْمَدُ الصَّاوِي ( ت١٢٤١هـ ) رَحِمَهُ اللَّهُ عَلَى قَوْلِ العَلَّامَةِ الدَّرْدِيرِ رَحِمَهُ اللَّهُ: وَلَا يُرْقَى بِالأَسْمَاءِ الَّتِي لَا يُعْرَفُ مَعْنَاهَا: أَيْ: مَا لَمْ تَكُنْ مَرْوِيَّةً عَنْ ثِقَةٍ ۞ كَالمَأْخُوذَةِ مِنْ كَلَامِ أَبِي الحَسَنِ الشَّاذِلِيِّ

وَقَدْ تَكَلَّمَ شُرَّاحُ الأَدْعِيَةِ الشَّاذِلِيَّةِ بِالتَّفْصِيلِ عَلَى تِلْكَ الكَلِمَاتِ بِمَا ظَهَرَ لَهُمْ مِنَ الاحْتِمَالَاتِ بِحَسَبِ السِّيَاقِ وَالقَرَائِنِ ۞ أَوْ بِحَسَبِ مَا بَلَغَهُمْ مِنَ الرِّوَايَاتِ ۞ مِنْ ذَلِكَ قَوْلُ الشَّيْخِ أَبِي الحَسَنِ فِي حِزْبِ الحَمْدِ وَحِزْبِ اللُّطْفِ وَالحَفِيظَةِ: «أَحُونْ ۞ قَافْ ۞ أَدُمَّ ۞ حَمَّ ۞ هَاءُ ۞ أَمِينْ» ۞ فَمِنَ الشُّرَّاحِ مَنْ قَالَ هِيَ أَسْمَاءٌ لِلَّهِ تَعَالَى أُلْهِمَهَا لَكِنَّهَا بِغَيْرِ اللِّسَانِ العَرَبِيِّ ۞ فَمَدْلُولُ الأَوَّلِ اسْمُهُ تَعَالَى الحَيُّ ۞ وَالثَّانِي القَيُّومُ ۞ وَالثَّالِثُ الدَّائِمُ أَوِ المُهَيْمِنُ ۞ وَالرَّابِعُ ذُو الجَلَالِ وَالإِكْرَامِ ۞ وَالخَامِسُ الرَّحِيمُ ۞ وَالسَّادِسُ الرَّحْمَنُ ۞ وَمِنْهُمْ مَنْ قَالَ: إِنَّ جَمِيعَهَا كَلِمَةٌ وَاحِدَةٌ تُقْرَأُ بِالوَصْلِ هَكَذَا: «أَحُونْ قَافْ ادُمَّ حَمَّ هَاءُ امِينْ» ۞ وَهِيَ تَدُلُّ عَلَى اسْمٍ مِنْ أَسْمَاءِ اللَّهِ العَظِيمَةِ ۞ وَلَكِنَّهُ بِغَيْرِ اللِّسَانِ العَرَبِيِّ

وَيَشْهَدُ لِجَوَازِ اخْتِصَاصِ اللَّهِ تَعَالَى بَعْضَ عِبَادِهِ بِمَعْرِفَةِ اسْمٍ مِنْ أَسْمَائِهِ عَزَّ وَجَلَّ الحَدِيثُ الَّذِي رَوَاهُ الإِمَامُ أَحْمَدُ وَصَحَّحَهُ ابْنُ حِبَّانَ وَهُوَ قَوْلُ النَّبِيِّ ﷺ فِي بَعْضِ أَدْعِيَتِهِ: «أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ۞ سَمَّيْتَ بِهِ نَفْسَكَ ۞ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ ۞ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ ۞ أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ»

قَالَ الشَّيْخُ تَاجُ الدِّينِ الفَاكِهَانِيُّ ( ت٧٢٤هـ ): فِيهِ دَلَالَةٌ ظَاهِرَةٌ عَلَى اخْتِصَاصِ بَعْضِ النَّاسِ بِبَعْضِ أَسْمَائِهِ تَعَالَى

وَالحَدِيثُ نَفْسُهُ أَوْرَدَهُ الخَطِيبُ التِّبْرِيزِيُّ ( ت٧٤١هـ ) فِي مِشْكَاةِ المَصَابِيحِ وَفِيهِ بَعْدَ قَوْلِهِ: «أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ»: «أَوْ أَلْهَمْتَهُ عِبَادَكَ»

قَالَ الشَّيْخُ عَلِيٌّ القَارِي ( ت١٠١٤هـ ): «وَأَلْهَمْتَهُ عِبَادَكَ» بِغَيْرِ وَاسِطَةٍ ۞ وَهِيَ أَسْمَاؤُهُ فِي اللُّغَاتِ المُخْتَلِفَةِ

وَفِي مَوَاضِعَ أُخَرَ يَأْتِي الشَّيْخُ أَبُو الحَسَنِ رَحِمَهُ اللَّهُ بِالحُرُوفِ المُقَطَّعَةِ الَّتِي اسْتُفْتِحَتْ بِهَا بَعْضُ سُوَرِ القُرْآنِ الكَرِيمِ ۞ مَعَ مَا يُشِيرُ إِلَى أَنَّهُ يَعْتَبِرُهَا رُمُوزًا عَلَى أَسْمَاءٍ أَوْ صِفَاتٍ ثَابِتَةٍ لِلَّهِ تَعَالَى ۞ فَيَسْأَلُ اللَّهَ تَعَالَى بِهَا ۞ أَوْ أَنَّهُ يَعْتَبِرُهَا رُمُوزًا عَلَى بَعْضِ أَفْعَالِهِ تَعَالَى فَيَسْأَلُ اللَّهَ إِيَّاهَا

فَإِذَا أَوْرَدَ قَوْلَهُ تَعَالَى: §Q§مريم: ١|كهيعص ١§Q§ فَعَلَى الأَوَّلِ كَأَنَّهُ يَقُولُ: يَا كَافٍ ۞ يَا هَادٍ ۞ يَا وَلِيُّ ۞ يَا عَلِيمُ ۞ يَا صَادِقَ الوَعْدِ ۞ وَعَلَى الثَّانِي فَهُوَ يَسْأَلُ اللَّهَ تَعَالَى الكِفَايَةَ وَالهِدَايَةَ وَالوِلَايَةَ وَالعِنَايَةَ وَالإِجَابَةَ

وَإِذَا أَوْرَدَ قَوْلَهُ تَعَالَى: §Q§الشورى: ١ - ٢|حم ١ عسق ٢§Q§ فَعَلَى الأَوَّلِ كَأَنَّهُ يَقُولُ: يَا حَيُّ يَا قَيُّومُ ۞ يَا عَلِيمُ ۞ يَا سَلَامُ ۞ يَا قَيُّومُ ۞ وَعَلَى الثَّانِي فَهُوَ يَسْأَلُ اللَّهَ تَعَالَى الحِمَايَةَ وَالعِنَايَةَ وَالإِعَانَةَ عَلَى القِيَامِ بِأَمْرِهِ عَزَّ وَجَلَّ ۞ إِلَى غَيْرِ ذَلِكَ مِمَّا أَوْرَدَهُ الشُّرَّاحُ ۞ لَا سِيَّمَا الإِمَامُ الرَّبَّانِيُّ أَحْمَدُ زَرُّوقٌ رَحِمَهُ اللَّهُ فِي شَرْحِهِ الكَبِيرِ وَالصَّغِيرِ عَلَى حِزْبِ البَحْرِ ۞ وَفِي حَلِّهِ لِمُشْكِلَاتِ الحِزْبِ الكَبِيرِ ۞ وَقَدْ قَالَ فِيهِ: «وَهَذَا مُوَافِقٌ لِمَقَاصِدِ الشَّرْعِ ۞ وَالمَقْصُودُ مِنَ العُبُودِيَّةِ ۞ وَالاتِّبَاعِ وَالدَّعْوَةِ إِلَى اللَّهِ عَلَى البَصِيرَةِ وَالنُّورِ الوَاضِحِ»

وَقَدْ يَأْتِي الشَّيْخُ أَبُو الحَسَنِ رَحِمَهُ اللَّهُ بِرُمُوزٍ يُشِيرُ بِهَا إِلَى بَعْضِ مَخْلُوقَاتِ اللَّهِ تَعَالَى ۞ كَمَا فِي قَوْلِهِ فِي حِزْبِ الحَمْدِ: «ق ج سِرَّانِ مِنْ سِرِّكَ ۞ وَكِلَاهُمَا دَالَّانِ عَلَى غَيْرِكَ ۞ فَبِالسِّرِّ الجَامِعِ الدَّالِّ عَلَيْكَ لَا تَدَعْنِي لِغَيْرِكَ» ۞ وَهَذَا لَا يُعْلَمُ إِلَّا بِالنَّقْلِ عَنِ الشَّيْخِ ۞ وَقَدْ وَقَفْتُ عَلَى قَوْلِ الشَّيْخِ أَبِي عَبْدِ اللَّهِ ابْنِ الصَّبَّاغِ: سَمِعْتُ سَيِّدِي أَبَا العَزَائِمِ مَاضِيَ بْنَ سُلْطَانٍ رَحِمَهُ اللَّهُ يَقُولُ: القَافُ: قَلْبُ الإِنْسَانِ ۞ وَالجِيمُ جِسْمُهُ ۞ وَكِلَاهُمَا دَالٌّ عَلَى غَيْرِ اللَّهِ تَعَالَى لِأَنَّ القَلْبَ مِنْ طَبْعِهِ المَيْلُ إِلَى الهَوَى ۞ وَالجِسْمُ مِنْ طَبْعِهِ المَيْلُ إِلَى الشَّهْوَةِ ۞ وَهُمَا مُبْعِدَانِ عَنِ اللَّهِ تَعَالَى ۞ فَإِذَا كَانَا دَالَّيْنِ عَلَى غَيْرِ اللَّهِ تَعَالَى لَمْ يَتَوَسَّلِ الشَّيْخُ رَضِيَ اللَّهُ عَنْهُ بِهِمَا ۞ وَتَوَسَّلَ بِالسِّرِّ الجَامِعِ الدَّالِّ عَلَى اللَّهِ تَعَالَى وَهُوَ مُحَمَّدٌ ﷺ لِأَنَّهُ قَلْبٌ وَجِسْمٌ ۞ وَكُلٌّ مِنْهُمَا دَالٌّ عَلَى اللَّهِ تَعَالَى

وَمِمَّا قَدْ يُسْتَشْكَلُ مِنْ بَعْضِ أَدْعِيَةِ الشَّيْخِ إِقْسَامُهُ عَلَى اللَّهِ تَعَالَى ۞ كَقَوْلِهِ فِي الحِزْبِ الكَبِيرِ وَغَيْرِهِ: «أَقْسَمْتُ عَلَيْكَ» ۞ وَأُجِيبَ بِجَوَازِهِ لِمَا صَحَّ عَنِ النَّبِيِّ ﷺ مِنْ قَوْلِهِ: إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ ۞ وَقَدْ قَالَهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ لَمَّا قَالَ أَنَسُ بْنُ النَّضْرِ رَضِيَ اللَّهُ عَنْهُ: «أَتُكْسَرُ ثَنِيَّةُ الرُّبَيِّعِ يَا رَسُولَ اللَّهِ؟! لَا وَالَّذِي بَعَثَكَ بِالحَقِّ لَا تُكْسَرُ ثَنِيَّتُهَا» ۞ فَإِنَّهُ حَلَفَ لَا تُكْسَرُ ثَنِيَّةُ الرُّبَيِّعِ قِصَاصًا مُحْسِنًا لِظَنِّهِ بِاللَّهِ تَعَالَى بِأَنْ يُلْقِيَ فِي قُلُوبِ أَوْلِيَاءِ القِصَاصِ العَفْوَ ۞ فَكَانَ كَذَلِكَ ۞ وَلَمْ يُنْكِرْ عَلَيْهِ النَّبِيُّ ﷺ قَسَمَهُ ۞ وَلَمْ يَعْتَبِرْهُ تَأَلِّيًا عَلَى اللَّهِ تَعَالَى ۞ بَلْ جَعَلَ إِبْرَارَهُ كَرَامَةً لَهُ

وَقَدْ قَالَ القَاضِي عِيَاضٌ رَحِمَهُ اللَّهُ فِي الإِكْمَالِ: «فِيهِ إِشَارَةٌ إِلَى إِجَابَةِ دَعْوَتِهِ وَعَظِيمِ مَكَانَتِهِ عِنْدَ رَبِّهِ ۞ وَأَنَّهُ لَا يُخَيَّبُ أَمَلَهُ فِيهِ ۞ وَلَا يُكَذِّبُ ظَنَّهُ بِهِ ۞ وَلَا يَرُدُّ دَعْوَتَهُ وَرَغْبَتَهُ وَعَزِيمَتَهُ وَقَسَمَهُ فِي سُؤَالِهِ بِصِدْقِ تَوَكُّلِهِ عَلَيْهِ وَتَفْوِيضِهِ إِلَيْهِ» ۞ وَقَالَ أَيْضًا: وَفِيهِ صِحَّةُ كَرَامَاتِ الأَوْلِيَاءِ

وَمِمَّا يُسْتَشْكَلُ أَيْضًا قَوْلُهُ فِي الحِزْبِ الكَبِيرِ: «وَلَيْسَ مِنَ الكَرَمِ أَنْ لَا تُحْسِنَ إِلَّا لِمَنْ أَحْسَنَ إِلَيْكَ» ۞ وَوُجِّهَ بِأَنَّهُ كَلَامٌ صَادِرٌ مِنَ الشَّيْخِ فِي حَالِ الإِدْلَالِ ۞ وَهُوَ انْبِسَاطٌ يَثُورُ مِنْ مَقَامِ الأُنْسِ وَالتَّحَقُّقِ بِالمَحَبَّةِ الخَاصَّةِ ۞ وَلَا يَصِحُّ إِلَّا مِنْ أَكَابِرِ الأَنْبِيَاءِ وَالأَوْلِيَاءِ المُتَحَقِّقِينَ بِمَقَامِ المَحْبُوبِيَّةِ ۞ المُتَحَفِينَ بِغَايَةِ الخُصُوصِيَّةِ

وَمِنْهُ قَوْلُ سَيِّدِنَا مُوسَى عَلَى نَبِيِّنَا وَعَلَيْهِ الصَّلَاةُ وَالسَّلَامُ: §Q§الأعراف: ١٥٥|أَتُهلِكُنا بِما فَعَلَ السُّفَهاءُ مِنّا§Q§ ۞ وَعُدَّ مِنْهُ أَيْضًا قَوْلُ إِبْرَاهِيمَ عَلَى نَبِيِّنَا وَعَلَيْهِ الصَّلَاةُ وَالسَّلَامُ: §Q§البقرة: ٢٦٠|رَبِّ أَرِنى كَيفَ تُحْيِ المَوتىٰ§Q§ ۞ فَإِنَّ ظَاهِرَهُ دُخُولُ الشَّكِّ عَلَى قَلْبِهِ فِي إِحْيَاءِ المَوْتَى ۞ لَكِنَّ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَدَّهَا أَرْجَى آيَةٍ كَمَا نَقَلَ الطَّبَرِيُّ عَنْهُ ۞ وَوَجَّهَهُ ابْنُ عَطِيَّةَ بِأَنَّهَا كَانَتْ كَذَلِكَ لِمَا فِيهَا مِنَ الإِدْلَالِ عَلَى اللَّهِ وَسُؤَالِ الإِحْيَاءِ فِي الدُّنْيَا وَلَيْسَتْ مَظِنَّةً لِذَلِكَ

وَوُجِّهَ أَيْضًا بِأَنَّهُ يُخَاطِبُ نَفْسَهُ قَاصِدًا الاسْتِدْلَالَ عَلَى عَدَمِ اخْتِصَاصِ إِحْسَانِ اللَّهِ عَزَّ وَجَلَّ بِمَنْ أَطَاعَهُ ۞ وَأَنَّ الكَرِيمَ لَا يُبَالِي فِي إِحْسَانِهِ بِمَنْ وَافَقَهُ وَلَا بِمَنْ خَالَفَهُ ۞ كَأَنَّهُ يَقُولُ لِنَفْسِهِ مُسْتَدِلًّا بِالعُرْفِ وَالأَمْرِ الجَارِي فِي الشَّاهِدِ: وَلَيْسَ مِنَ الكَرَمِ الجَارِي بَيْنَ الخَلْقِ أَنْ لَا يُحْسِنَ أَحَدُنَا إِلَّا لِمَنْ أَحْسَنَ إِلَيْكَ ۞ مَعَ أَنَّ الفَقْرَ وَالافْتِقَارَ وَصْفُنَا ۞ فَخَرَجَ كَلَامُهُ مَخْرَجَ الدَّلَالَةِ بِأَمْرٍ عُرْفِيٍّ عَلَى عَظِيمِ فَضْلِ اللَّهِ وَإِحْسَانِهِ

وَلَا يُسْتَبْعَدُ أَنَّ الشَّيْخَ أَبَا الحَسَنِ رَحِمَهُ اللَّهُ قَصَدَ هَذَا المَعْنَى ۞ وَأَخَذَهُ مِنْ قَوْلِ الأُسْتَاذِ أَبِي القَاسِمِ القُشَيْرِيِّ ( ت٤٦٥هـ ) فِي كِتَابِ التَّحْبِيرِ لَهُ: «وَلَيْسَتِ الفُتُوَّةُ أَنْ تُحْسِنَ إِلَى مَنْ أَحْسَنَ إِلَيْكَ ۞ لِأَنَّ ذَلِكَ جَزَاءٌ وَمُكَافَأَةٌ ۞ وَلَكِنِ الفُتُوَّةُ: أَنْ تُحْسِنَ إِلَى مَنْ أَسَاءَ إِلَيْكَ»

عَلَى أَنَّ الشَّيْخَ أَبَا الحَسَنِ رَحِمَهُ اللَّهُ دَفَعَ مَا أَوْهَمَتْهُ العِبَارَةُ مِنْ أَنَّ أَحَدًا مِنَ الخَلْقِ يُحْسِنُ إِلَى اللَّهِ تَعَالَى بِقَوْلِهِ: وَأَنْتَ الغَنِيُّ أَيِ الَّذِي لَا يَصِحُّ إِحْسَانُ أَحَدٍ إِلَيْهِ لِإِطْلَاقِ غِنَاهُ ۞ وَالمِفْضَالُ الَّذِي الكُلُّ مِنْ فَضْلِهِ وَإِحْسَانِهِ

وَمَعَ اتِّجَاهِ هَذِهِ المَحَامِلِ وَصِحَّتِهَا نَبَّهَ العُلَمَاءُ قَارِئَ هَذَا الدُّعَاءِ إِذَا وَصَلَ إِلَى هَذَا المَوْضِعِ بِقَوْلِهِمْ: مَنْ كَانَ لَهُ مَعَ اللَّهِ بَسْطُ حَالٍ وَإِدْلَالٍ فَلْيَأْتِ بِهَذِهِ الكَلِمَاتِ ۞ وَمَنْ لَيْسَ لَهُ ذَلِكَ فَلْيُجَاوِزْهَا إِلَى مَا بَعْدَهَا مِنْ قَوْلِهِ: §Q§الأعراف: ٢٣|رَبَّنا ظَلَمنا أَنفُسَنا وَإِن لَم تَغفِر لَنا وَتَرحَمنا لَنَكونَنَّ مِنَ الخٰسِرينَ ٢٣§Q§

وَقَالَ الشَّيْخُ زَرُّوقٌ فِيمَا كَتَبَهُ عَلَى الحِزْبِ الكَبِيرِ: «وَقَدْ رَأَيْتُ بِخَطِّ ابْنِ عَبَّادٍ رَحِمَهُ اللَّهُ أَنَّهُ لَا يَصْلُحُ أَنْ يَقُولَهُ إِلَّا مُدِلٌّ ۞ وَذَكَرَ عَنْ جُمْلَةٍ مِنَ السَّادَاتِ تَجَنُّبَ هَذَا اللَّفْظِ وَإِسْقَاطَهُ عِنْدَ قِرَاءَةِ الحِزْبِ لِكَوْنِهِ يَخُصُّ وَلَا يَعُمُّ»

وَمِمَّا يُسْتَشْكَلُ أَيْضًا سُؤَالُ الشَّيْخِ أَبِي الحَسَنِ الشَّاذِلِيِّ العِصْمَةَ ۞ كَقَوْلِهِ فِي الحِزْبِ الكَبِيرِ: «وَاكْسُنَا جَلَابِيبَ العِصْمَةِ فِي الأَنْفَاسِ وَاللَّحَظَاتِ» ۞ وَقَوْلِهِ فِي حِزْبِ البَحْرِ: «نَسْأَلُكَ العِصْمَةَ فِي الحَرَكَاتِ وَالسَّكَنَاتِ»

وَأُجِيبَ عَنْ ذَلِكَ بِأَنَّهُ طَلَبٌ لِلْعِصْمَةِ بِمَعْنَى الحِفْظِ ۞ لَا العِصْمَةِ الخَاصَّةِ بِالأَنْبِيَاءِ عَلَيْهِمُ السَّلَامُ ۞ وَقَدْ ثَبَتَ جَوَازُ طَلَبِهَا مِنَ اللَّهِ تَعَالَى مَعَ قَصْدِ ذَلِكَ المَعْنَى بِأَدِلَّةٍ شَرْعِيَّةٍ

فَمِنَ القُرْآنِ قَوْلُهُ تَعَالَى: §Q§الحج: ٨٨|وَاعتَصِموا بِاللَّهِ§Q§ ۞ قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: «سَلُوا رَبَّكُمْ أَنْ يَعْصِمَكُمْ مِنْ كُلِّ مَا يَسْخَطُ وَيَكْرَهُ»

وَمِنَ السُّنَّةِ مَا رَوَاهُ ابْنُ مَاجَهْ بِسَنَدٍ صَحِيحٍ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «إِذَا دَخَلَ أَحَدُكُمُ المَسْجِدَ فَلْيُسَلِّمْ عَلَى النَّبِيِّ ﷺ وَلْيَقُلْ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ ۞ وَإِذَا خَرَجَ ۞ فَلْيُسَلِّمْ عَلَى النَّبِيِّ ﷺ وَلْيَقُلْ: اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ»

وَأَيْضًا مِنَ الأَدْعِيَةِ الَّتِي عَلَّمَهَا رَسُولُ اللَّهِ ﷺ لِأُمَّتِهِ قَوْلُهُ: «اللَّهُمَّ إِنِّي أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ ۞ وَعَزَائِمَ مَغْفِرَتِكَ ۞ وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ»

قَالَ العِرَاقِيُّ: فِيهِ جَوَازُ سُؤَالِ العِصْمَةِ مِنْ كُلِّ الذُّنُوبِ ۞ وَقَدْ أَنْكَرَ بَعْضُهُمْ جَوَازَ ذَلِكَ ۞ إِذِ العِصْمَةُ إِنَّمَا هِيَ لِلْأَنْبِيَاءِ وَالمَلَائِكَةِ ۞ وَالجَوَابُ أَنَّهَا فِي حَقِّ الأَنْبِيَاءِ وَالمَلَائِكَةِ وَاجِبَةٌ ۞ وَفِي حَقِّ غَيْرِهِمْ جَائِزَةٌ ۞ وَسُؤَالُ الجَائِزِ جَائِزٌ

وَمِنْ هُنَا سَأَلَهَا الكَثِيرُ مِنَ الأَئِمَّةِ ۞ كَقَوْلِ الإِمَامِ خَلِيلٍ فِي مُقَدِّمَةِ مُخْتَصَرِهِ الفِقْهِيِّ: «وَاللَّهُ يَعْصِمُنَا مِنَ الزَّلَلِ» ۞ قَالَ العَلَّامَةُ العَدَوِيُّ: المُؤَلِّفُ مِنَ العُلَمَاءِ العَامِلِينَ الَّذِينَ يُقَلَّدُونَ فِي الأَقْوَالِ وَالأَفْعَالِ ۞ فَإِنْ قُلْتَ: العِصْمَةُ خَاصَّةٌ بِالأَنْبِيَاءِ وَالمَلَائِكَةِ؟ قُلْتُ: تِلْكَ العِصْمَةُ الوَاجِبَةُ ۞ لَا الجَائِزَةُ ۞ وَالمَقْصُودُ بِالدُّعَاءِ هَذَا الثَّانِي

عَلَى أَنَّ الشَّيْخَ دَاوُدَ بْنَ بَاخِلَا قَالَ فِي شَرْحِ حِزْبِ البَحْرِ: مَا سَأَلَ الشَّيْخُ رَضِيَ اللَّهُ عَنْهُ العِصْمَةَ مِنَ المَعْصِيَةِ ۞ وَإِنَّمَا سَأَلَ العِصْمَةَ مِنَ الشُّكُوكِ وَالظُّنُونِ وَالأَوْهَامِ ۞ وَلَا سَأَلَ العِصْمَةَ مِنْ هَذِهِ الأَشْيَاءِ مُطْلَقًا ۞ وَإِنَّمَا سَأَلَ العِصْمَةَ مِنَ النَّوْعِ الَّذِي يَصُدُّ القَلْبَ عَنِ الإِيمَانِ بِالغَيْبِ ۞ وَهَذَا أَمْرٌ مُتَعَيِّنٌ عَلَى كُلِّ عَبْدٍ ۞ وَمَطْلُوبٌ مِنْ كُلِّ مُكَلَّفٍ أَنْ يَكُونَ بِهَذِهِ الصِّفَةِ ۞ وَلَوْلَا رَحْمَةُ اللَّهِ تَعَالَى لَكَانَ العَبْدُ مُكَلَّفًا بِأَنْ لَا يَخْطُرَ بِقَلْبِهِ شَكٌّ وَلَا وَهْمٌ وَلَا خَاطِرٌ ۞ وَلَكِنَّ اللَّهَ خَفَّفَ عَنْهُ بِأَنَّهُ إِذَا خَطَرَ وَلَمْ يَثْبُتْ وَرَجَعَ إِلَى وَصْفِ إِيمَانِهِ أَنَّ ذَلِكَ لَا يَضُرُّهُ

هَذَا وَقَدِ اعْتَنَى شُرَّاحُ أَدْعِيَةِ الشَّيْخِ أَبِي الحَسَنِ رَحِمَهُ اللَّهُ بِتَوْجِيهِ مَا يُشْكِلُ مِنْهَا ۞ أَبْرَزُهُمُ الإِمَامُ زَرُّوقٌ رَحِمَهُ اللَّهُ القَائِلُ فِي أَوَّلِ تَعْلِيقِهِ عَلَى الحِزْبِ الكَبِيرِ: أَجْمَعَ جُمْهُورُ المُتَأَخِّرِينَ ـ بَلْ كُلُّ هَذِهِ الأَعْصَارِ ـ عَلَى قَبُولِ هَذِهِ الأَحْزَابِ وَالعَمَلِ عَلَيْهَا فِي سَائِرِ الأَقْطَارِ ۞ إِلَّا مَنْ قَلَّ فَلَاحُهُ ۞ وَظَهَرَتْ آثَارُ الابْتِلَاءِ عَلَيْهِ ۞ فَتَفَوَّقَتْ سِهَامُ الإِنْكَارِ مِنْ وَجْهٍ إِلَيْهِ ۞ وَعَلَيْهِ يَعُودُ وَبَالُ إِنْكَارِهِ ۞ وَإِلَيْهِ يَرْجِعُ نَقْصُهُ فِي جَمِيعِ أَخْبَارِهِ ۞ وَعَنْ قَرِيبٍ يَنْكَشِفُ الحَقُّ مِنَ البَاطِلِ ۞ وَيَتَبَيَّنُ الخَالِي مِنَ العَاطِلِ

❊ وَالحَقُّ يَظْهَرُ مِنْ مَعْنًى وَمِنْ كَلِمْ ❊

ثُمَّ اعْلَمْ أَنَّ الكَلَامَ كُلَّهُ ـ مِنْ دُعَاءٍ أَوْ غَيْرِهِ ـ إِمَّا أَنْ يَكُونَ مُوَافِقًا لِلشَّرِيعَةِ ۞ أَوْ لِلْحَقِيقَةِ ۞ أَوْ لَهُمَا ۞ أَوْ خَارِجًا عَنْهُمَا: 

فَإِنْ كَانَ خَارِجًا عَنْهُمَا بِحَيْثُ لَا يُوَافِقُ أَصْلًا وَلَا فَرْعًا فَهُوَ مَرْدُودٌ مِمَّنْ كَانَ بُرُوزُهُ ۞ فِي أَيِّ مَقَامٍ كَانَ

وَإِنْ كَانَ مُوَافِقًا لَهُمَا بِكُلِّ وَجْهٍ فَقَبُولُهُ لَازِمٌ ۞ وَرَدُّهُ تَعَسُّفٌ وَظُلْمٌ وَإِذَايَةٌ لِلْمُؤْمِنِينَ ۞ §Q§الأحزاب: ٥٨|وَالَّذينَ يُؤذونَ المُؤمِنينَ وَالمُؤمِنٰتِ بِغَيرِ مَا اكتَسَبوا فَقَدِ احتَمَلوا بُهتٰنًا وَإِثمًا مُبينًا ٥٨§Q§ ۞ وَ«مَنْ آذَى وَلِيًّا فَقَدْ بَارَزَ اللَّهَ بِالمُحَارَبَةِ»

وَإِنْ كَانَ مُخَالِفًا لِأَحَدِهِمَا بِوَجْهٍ يَقْبَلُ التَّأْوِيلَ تَعَيَّنَ رَدُّهُ لِلْآخَرِ بِتَأْوِيلِ القَابِلِ ۞ إِنْ ثَبَتَتْ مَزِيَّةُ صَاحِبِهِ ۞ بِخِلَافِ مَا لَا يَقْبَلُ التَّأْوِيلَ ۞ أَوْ لَا مَزِيَّةَ لِصَاحِبِهِ

وَالمَزِيَّةُ المُعْتَبَرَةُ فِي ذَلِكَ هُوَ العِلْمُ النَّافِعُ ۞ وَالعَمَلُ الصَّالِحُ ۞ وَالحَالُ الصَّحِيحُ ۞ وَكُلُّ ذَلِكَ مِمَّا نُقِلَ عَنْ حَالِ سَيِّدِي أَبِي الحَسَنِ رَضِيَ اللَّهُ عَنْهُ تَوَاتُرًا ۞ وَكَلَامُهُ شَاهِدٌ بِهِ جِبِلَّةً وَصُورَةً وَبُرْهَانًا وَتَنْوِيرًا ۞ فَلَزِمَ مُرَاعَاتُهُ وَاعْتِبَارُهُ»

وَقَالَ قَبْلَهُ الفَقِيهُ المَالِكِيُّ أَبُو القَاسِمِ البُرْزُلِيُّ ( ت٨٤١هـ ) فِي مُنَاقَشَتِهِ لِابْنِ تَيْمِيَّةَ ( ت٧٢٨هـ ) فِيمَا انْتَقَدَهُ عَلَى أَدْعِيَةِ الشَّيْخِ أَبِي الحَسَنِ الشَّاذِلِيِّ: رَأَيْتُ كَثِيرًا مِنَ الفُقَهَاءِ العَصْرِيِّينَ وَالعُلَمَاءِ العَامِلِينَ لَهُمْ أَذْكَارٌ مَخْصُوصَةٌ أَلَّفُوهَا فَتَرَاهُمْ يَرْكَنُونَ إِلَيْهَا لِأَنَّهَا صَارَتْ مَحْفُوظَةً لَهُمْ ۞ لَا أَنَّهُمُ اتَّخَذُوهَا سُنَّةً تُرْوَى عَنْهُمْ ۞ وَإِنَّمَا اعْتَادُوهَا فِي أَنْفُسِهِمْ وَتَيَسَّرَتْ عَلَيْهِمْ ۞ فَأَخَذَهَا النَّاسُ عَنْهُمْ مِنْ أَتْبَاعِهِمْ وَغَيْرِ أَتْبَاعِهِمْ

وَقَدْ أَلَّفْتُ أَنَا حِزْبَيِ الشَّيْخِ أَبِي الحَسَنِ الشَّاذِلِيِّ: الحِزْبَ الكَبِيرَ ۞ وَحِزْبَ البَحْرِ ۞ وَأَضَفْتُ إِلَى ذَلِكَ أَذْكَارًا أُخْرَى مِثْلَ الأَسْمَاءِ الحُسْنَى عَلَى طَرِيقِ اسْتِقْرَائِهَا مِنَ القُرْآنِ ۞ وَفِي أَثْنَائِهَا أَدْعِيَةٌ ۞ وَأَضَفْتُ إِلَيْهَا أَذْكَارًا أُخْرَى وَرَدَتْ فِي الأَحَادِيثِ ۞ وَأَدْعِيَةً كَثِيرَةً وَرَدَتْ فِي الصَّحِيحِ وَغَيْرِهِ ۞ وَأَدْعِيَةً فِي القُرْآنِ ۞ وَرَأَيْتُ لِذَلِكَ بَرَكَةً كَثِيرَةً ۞ وَالحَمْدُ لِلَّهِ تَعَالَى''',
);
